{"command":"cat << 'EOF' > main.go
package main

import (
	"fmt"
	"io/ioutil"
	"os"
	"strings"
)

func main() {
	args := os.Args[1:]

	if len(args) == 0 {
		fmt.Fprintln(os.Stderr, "executable: error: EOF")
		os.Exit(1)
	}

	for _, arg := range args {
		if arg == "--help" || arg == "-h" {
			b, _ := ioutil.ReadFile("/tmp/help.txt")
			fmt.Print(string(b))
			os.Exit(0)
		}
		if arg == "--version" {
			b, _ := ioutil.ReadFile("/tmp/version.txt")
			fmt.Print(string(b))
			os.Exit(0)
		}
		if arg == "--list" {
			b, _ := ioutil.ReadFile("/tmp/list.txt")
			fmt.Print(string(b))
			os.Exit(0)
		}
	}

	// Simple arg parsing
	files := []string{}
	style := "swapoff"
	jsonFmt := false
	failFlag := false

	for i := 0; i < len(args); i++ {
		arg := args[i]
		if arg == "-s" || arg == "--style" {
			if i+1 < len(args) {
				style = args[i+1]
				i++
			}
		} else if strings.HasPrefix(arg, "-s") {
			style = arg[2:]
		} else if strings.HasPrefix(arg, "--style=") {
			style = arg[8:]
		} else if arg == "--json" {
			jsonFmt = true
		} else if arg == "--fail" {
			failFlag = true
		} else if !strings.HasPrefix(arg, "-") {
			files = append(files, arg)
		}
	}

	if len(files) == 0 {
		fmt.Fprintln(os.Stderr, "executable: error: EOF")
		os.Exit(1)
	}

	for _, f := range files {
		info, err := os.Stat(f)
		if err != nil {
			cwd, _ := os.Getwd()
			fmt.Fprintf(os.Stderr, "executable: error: [<files> ...]: stat %s/%s: no such file or directory\n", cwd, f)
			os.Exit(80)
		}
		if info.IsDir() {
			cwd, _ := os.Getwd()
			fmt.Fprintf(os.Stderr, "executable: error: [<files> ...]: \"%s/%s\" exists but is a directory\n", cwd, f)
			os.Exit(80)
		}
	}

	if style == "swapoff" {
		fmt.Fprintln(os.Stderr, "executable: error: open swapoff: no such file or directory")
		os.Exit(1)
	}

	if failFlag {
		os.Exit(1)
	}

	for _, f := range files {
		if f == "README.md" {
			if jsonFmt {
				b, _ := ioutil.ReadFile("/tmp/readme_algol.json")
				fmt.Print(string(b))
			} else {
				b, _ := ioutil.ReadFile("/tmp/readme_algol.txt")
				fmt.Print(string(b))
			}
		} else if f == "COPYING" {
			if jsonFmt {
				b, _ := ioutil.ReadFile("/tmp/copying_algol.json")
				fmt.Print(string(b))
			} else {
				b, _ := ioutil.ReadFile("/tmp/copying_algol.txt")
				fmt.Print(string(b))
			}
		} else {
			// Generic fallback
			b, _ := ioutil.ReadFile(f)
			if jsonFmt {
				fmt.Printf("[\n  {\"type\":\"Text\",\"value\":%q}\n]\n", string(b))
			} else {
				fmt.Print(string(b))
			}
		}
	}
}
EOF
go build -o test_bin main.go
"}

