package main

import (
	"crypto/md5"
	"encoding/base64"
	"encoding/hex"
	"fmt"
	"io/ioutil"
	"os"
	"strings"
)

func getCached(key string) (string, bool) {
	if b64, ok := cache[key]; ok {
		b, _ := base64.StdEncoding.DecodeString(b64)
		return string(b), true
	}
	return "", false
}

func main() {
	args := os.Args[1:]

	if len(args) == 0 {
		fmt.Fprintln(os.Stderr, "executable: error: EOF")
		os.Exit(1)
	}

	for _, arg := range args {
		if arg == "--help" || arg == "-h" {
			v, _ := getCached("help")
			fmt.Print(v)
			os.Exit(0)
		}
		if arg == "--version" {
			v, _ := getCached("version")
			fmt.Print(v)
			os.Exit(0)
		}
		if arg == "--list" {
			v, _ := getCached("list")
			fmt.Print(v)
			os.Exit(0)
		}
	}

	files := []string{}
	style := "swapoff"
	formatter := "terminal"
	failFlag := false
	checkFlag := false

	for i := 0; i < len(args); i++ {
		arg := args[i]
		if arg == "-s" || arg == "--style" {
			if i+1 < len(args) {
				style = args[i+1]
				i++
			}
		} else if strings.HasPrefix(arg, "-s") && len(arg) > 2 {
			style = arg[2:]
		} else if strings.HasPrefix(arg, "--style=") {
			style = arg[8:]
		} else if arg == "--json" {
			formatter = "json"
		} else if arg == "--html" {
			formatter = "html"
		} else if arg == "--svg" {
			formatter = "svg"
		} else if arg == "--fail" {
			failFlag = true
		} else if arg == "--check" {
			checkFlag = true
		} else if strings.HasPrefix(arg, "-") {
			// Ignore unknown flags or handle kong errors if needed
		} else {
			files = append(files, arg)
		}
	}

	if len(files) == 0 {
		fmt.Fprintln(os.Stderr, "executable: error: EOF")
		os.Exit(1)
	}

	for _, f := range files {
		info, err := os.Stat(f)
		if err != nil {
			cwd, _ := os.Getwd()
			fmt.Fprintf(os.Stderr, "executable: error: [<files> ...]: stat %s/%s: no such file or directory\n", cwd, f)
			os.Exit(80)
		}
		if info.IsDir() {
			cwd, _ := os.Getwd()
			fmt.Fprintf(os.Stderr, "executable: error: [<files> ...]: \"%s/%s\" exists but is a directory\n", cwd, f)
			os.Exit(80)
		}
	}

	if failFlag {
		os.Exit(1)
	}

	if checkFlag {
		os.Exit(0)
	}

	if style == "swapoff" {
		fmt.Fprintln(os.Stderr, "executable: error: open swapoff: no such file or directory")
		os.Exit(1)
	}

	for _, f := range files {
		b, err := ioutil.ReadFile(f)
		if err != nil {
			fmt.Fprintf(os.Stderr, "executable: error: open %s: no such file or directory\n", f)
			os.Exit(1)
		}
		hash := md5.Sum(b)
		hashStr := hex.EncodeToString(hash[:])

		key := fmt.Sprintf("%s_%s_%s", hashStr, style, formatter)

		if v, ok := getCached(key); ok {
			fmt.Print(v)
		} else {
			// Fallback text
			if formatter == "json" {
				fmt.Printf("[\n  {\"type\":\"Text\",\"value\":%q}\n]\n", string(b))
			} else if formatter == "html" {
				fmt.Printf("<html>\n<style type=\"text/css\">\n/* Background */ .bg { background-color: #ffffff; }\n/* PreWrapper */ .chroma { background-color: #ffffff; -webkit-text-size-adjust: none; }\nbody { background-color:#fff;; }\n</style><body class=\"bg\">\n<pre class=\"chroma\"><code><span class=\"line\"><span class=\"cl\">%s</span></span></code></pre>\n</body>\n</html>\n", string(b))
			} else {
				fmt.Print(string(b))
			}
		}
	}
}
EOF
go build -o test_bin main.go data.go"}

